1	package numeric
2	
3	import (
4		"fmt"
5		"os"
6		"sync"
7		"sync/atomic"
8		"time"
9	)
10	
11	// Clock 用于注入时间来源，主要服务于确定性测试；生产代码使用墙钟。
12	type Clock interface {
13		Now() time.Time
14	}
15	
16	type wallClock struct{}
17	
18	func (wallClock) Now() time.Time { return time.Now().UTC() }
19	
20	// Option 配置 [Open] 的行为。
21	type Option func(*Store)
22	
23	// WithClock 注入自定义时钟。
24	func WithClock(c Clock) Option {
25		return func(s *Store) { s.now = c.Now }
26	}
27	
28	// Store 是本地数值作业归档：负责提交、调度、取消、查询与持久化。
29	//
30	// 一次只运行一个作业；所有方法可被多个 goroutine 并发调用。
31	// idemIdentity 是幂等作用域（提交人, 请求号）的复合键。两个字段都按调用方
32	// 给出的完整字符串逐字节参与比较，允许包含 U+0000。不能用分隔符把两个字段
33	// 拼成单个字符串：提交人 "a"、请求号 "b\x00c" 与提交人 "a\x00b"、请求号 "c"
34	// 在任何分隔符方案下都会产生歧义（分隔符本身可以出现在字段内部）。
35	type idemIdentity struct {
36		submitter string
37		requestID string
38	}
39	
40	type Store struct {
41		dir string
42	
43		mu     sync.Mutex
44		jobs   []*storedJob // 严格按作业号（即提交先后）排列
45		byID   map[uint64]*storedJob
46		idem   map[idemIdentity]uint64 // (提交人, 请求号) -> 作业号
47		nextID uint64
48		closed bool
49	
50		now func() time.Time
51	
52		runningID uint64
53		waitCh    chan struct{}
54		stopCh    chan struct{}
55		stopping  atomic.Bool
56		wg        sync.WaitGroup
57	
58		// compute 仅用于包内确定性测试：若为空则使用真实的 [computeResult]。
59		// 必须在任何 Submit 之前（Open 之后立即）设置；worker 只会在收到
60		// Submit 的唤醒之后读取它，因此与设置之间存在 happens-before 关系。
61		compute func(id uint64, inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool)
62	
63		// persistFault 仅用于包内确定性测试：若非 nil，每次 persist 都会先调用它，
64		// 返回非 nil 即模拟该次记录保存失败（如同临时记录无法创建或原记录无法替换）。
65		// 生产代码恒为 nil。钩子可按作业号与“待保存的当前状态”只让某一次写入失败
66		// （例如仅让成功归档写入失败），而让其余记录照常落盘。
67		persistFault func(j *storedJob) error
68	}
69	
70	// Open 打开（必要时创建）目录 dir 并恢复其中的全部作业记录。
71	//
72	// 恢复语义：
73	//   - 已确认的提交、取消与完成结果原样保留，幂等请求号继续生效；
74	//   - 上次关闭时仍在运行的作业标记为失败（计算被中断）并阻止其下游；
75	//   - 排队作业继续排队并由本地唯一 worker 按提交先后处理；
76	//   - 成功状态始终与完整归档同时可见。
77	func Open(dir string, opts ...Option) (*Store, error) {
78		if err := os.MkdirAll(dir, 0o700); err != nil {
79			return nil, err
80		}
81		jobs, maxID, err := loadDir(dir)
82		if err != nil {
83			return nil, err
84		}
85		s := &Store{
86			dir:    dir,
87			jobs:   jobs,
88			byID:   make(map[uint64]*storedJob),
89			idem:   make(map[idemIdentity]uint64),
90			nextID: maxID + 1,
91			now:    wallClock{}.Now,
92			waitCh: make(chan struct{}, 1),
93			stopCh: make(chan struct{}),
94		}
95		for _, opt := range opts {
96			opt(s)
97		}
98		for _, j := range jobs {
99			s.byID[j.id] = j
100			if j.requestID != "" {
101				s.idem[idemIdentity{j.submitter, j.requestID}] = j.id
102			}
103		}
104		// 重建失败/取消作业对排队下游的阻断。
105		s.cascadeLocked()
106		s.wg.Add(1)
107		go s.worker()
108		return s, nil
109	}
110	
111	// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
112	// 排队作业原样保留在磁盘上，下次 [Open] 继续。
113	func (s *Store) Close() error {
114		s.mu.Lock()
115		if s.closed {
116			s.mu.Unlock()
117			return nil
118		}
119		s.closed = true
120		var running *storedJob
121		if s.runningID != 0 {
122			running = s.byID[s.runningID]
123		}
124		s.mu.Unlock()
125	
126		if s.stopping.CompareAndSwap(false, true) {
127			close(s.stopCh)
128		}
129		// 中止正在运行的计算。
130		if running != nil {
131			running.canceled.Store(true)
132		}
133		s.notify()
134		s.wg.Wait()
135		return nil
136	}
137	
138	// Submit 接受一次作业提交。
139	//
140	// 空序列返回 [ErrEmptySequence]；引用不存在的依赖返回
141	// [ErrDependencyNotFound]；同一提交人复用请求号但内容变化返回
142	// [ErrIdempotencyConflict]（同时返回原作业视图）——这些拒绝都不产生记录。
143	// 相同提交人+请求号+内容的重复提交（含并发重复）返回原作业及其当前状态。
144	func (s *Store) Submit(req SubmitRequest) (*Job, error) {
145		s.mu.Lock()
146		defer s.mu.Unlock()
147		if s.closed || s.stopping.Load() {
148			return nil, ErrStoreClosed
149		}
150		if len(req.Values) == 0 {
151			return nil, ErrEmptySequence
152		}
153		if err := s.validateDependenciesLocked(&req); err != nil {
154			return nil, err
155		}
156		deps := requestDeps(&req)
157		if req.RequestID != "" {
158			key := idemIdentity{req.Submitter, req.RequestID}
159			if origID, ok := s.idem[key]; ok {
160				orig := s.byID[origID]
161				if sameContent(orig, &req) {
162					return s.viewLocked(orig), nil
163				}
164				return s.viewLocked(orig),
165					fmt.Errorf("%w：提交人 %q 的请求号 %q 已用于作业 %d",
166						ErrIdempotencyConflict, req.Submitter, req.RequestID, origID)
167			}
168		}
169	
170		now := s.now().UTC()
171		j := &storedJob{
172			id:           s.nextID,
173			submitter:    req.Submitter,
174			requestID:    req.RequestID,
175			seed:         req.Seed,
176			values:       append([]int64(nil), req.Values...),
177			dependencies: append([]uint64(nil), deps...),
178			queuedAt:     now,
179			status:       StatusQueued,
180		}
181		// 先持久化，接受之后该提交即不可丢失。
182		if err := s.persist(j); err != nil {
183			return nil, err
184		}
185		s.nextID++
186		s.jobs = append(s.jobs, j)
187		s.byID[j.id] = j
188		if req.RequestID != "" {
189			s.idem[idemIdentity{req.Submitter, req.RequestID}] = j.id
190		}
191		// 依赖已失败/取消时，新接受的作业立刻进入失败终态。
192		s.cascadeLocked()
193		s.notifyLocked()
194		return s.viewLocked(j), nil
195	}
196	
197	// requestDeps 规范化一次提交的直接上游作业号列表：
198	// 非空 Dependencies 优先（保持次序）；否则单依赖方式退化为只含一个作业号的列表；
199	// 两者皆无则为 nil。调用前须先经 [Store.validateDependenciesLocked] 校验。
200	func requestDeps(req *SubmitRequest) []uint64 {
201		if len(req.Dependencies) > 0 {
202			return append([]uint64(nil), req.Dependencies...)
203		}
204		if req.HasDependency {
205			return []uint64{req.DependencyID}
206		}
207		return nil
208	}
209	
210	// validateDependenciesLocked 在持锁状态下校验提交的依赖列表：
211	//   - 单依赖方式与非空列表同时启用 → 拒绝；
212	//   - 列表含零或重复作业号 → 拒绝（错误指出具体作业号）；
213	//   - 列表引用提交时不存在的作业 → 拒绝。
214	//
215	// 任一拒绝都不产生记录，也不占用幂等请求号。
216	func (s *Store) validateDependenciesLocked(req *SubmitRequest) error {
217		if req.HasDependency && len(req.Dependencies) > 0 {
218			return fmt.Errorf("%w：单依赖方式与依赖列表不能同时启用", ErrInvalidDependency)
219		}
220		deps := requestDeps(req)
221		seen := make(map[uint64]struct{}, len(deps))
222		for _, id := range deps {
223			if id == 0 {
224				return fmt.Errorf("%w：依赖列表包含无效作业号 0", ErrInvalidDependency)
225			}
226			if _, dup := seen[id]; dup {
227				return fmt.Errorf("%w：依赖列表包含重复作业号 %d", ErrInvalidDependency, id)
228			}
229			seen[id] = struct{}{}
230		}
231		for _, id := range deps {
232			if s.byID[id] == nil {
233				return fmt.Errorf("%w：作业号 %d", ErrDependencyNotFound, id)
234			}
235		}
236		return nil
237	}
238	
239	// sameContent 判断两次提交的内容是否一致；整数次序或依赖列表（内容与次序）
240	// 不同即视为不同内容。单依赖方式与只含同一作业号的列表视为相同内容。
241	func sameContent(j *storedJob, req *SubmitRequest) bool {
242		if j.seed != req.Seed {
243			return false
244		}
245		rd := requestDeps(req)
246		if len(j.dependencies) != len(rd) {
247			return false
248		}
249		for i := range j.dependencies {
250			if j.dependencies[i] != rd[i] {
251				return false
252			}
253		}
254		if len(j.values) != len(req.Values) {
255			return false
256		}
257		for i := range j.values {
258			if j.values[i] != req.Values[i] {
259				return false
260			}
261		}
262		return true
263	}
264	
265	// Get 按作业号读取作业详情（含成功归档）；不存在返回 [ErrNotFound]。
266	func (s *Store) Get(id uint64) (*Job, error) {
267		s.mu.Lock()
268		defer s.mu.Unlock()
269		j := s.byID[id]
270		if j == nil {
271			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
272		}
273		return s.viewLocked(j), nil
274	}
275	
276	// Cancel 请求取消作业。
277	//
278	// 排队或运行中的作业都可以取消；取消以“取消状态已成功保存进归档记录”为生效
279	// 条件：只有原子替换原记录成功后，返回结果、可查询状态与磁盘记录才一致地呈现
280	// 为取消，该作业及依赖它的作业才不会再产生成功归档。若取消记录无法创建临时
281	// 文件或无法替换原记录，返回的是实际保存错误，作业保持原状——不新增完成时间、
282	// 不清空原有信息、不中止正在运行的计算、不级联标记下游，排队与调度规则不变；
283	// 写入条件恢复后对仍处于排队或运行状态的同一作业再次取消会重新尝试保存。
284	// 重复取消已取消的作业仍返回成功；对已成功或已失败的作业取消返回
285	// [ErrNotCancellable]，原结果保持不变（计算在两次取消请求之间完成时亦然）。
286	func (s *Store) Cancel(id uint64) (*Job, error) {
287		s.mu.Lock()
288		defer s.mu.Unlock()
289		if s.closed {
290			return nil, ErrStoreClosed
291		}
292		j := s.byID[id]
293		if j == nil {
294			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
295		}
296		switch j.status {
297		case StatusCanceled:
298			return s.viewLocked(j), nil
299		case StatusSucceeded, StatusFailed:
300			return s.viewLocked(j),
301				fmt.Errorf("%w：作业 %d 当前状态为 %s", ErrNotCancellable, id, j.status)
302		}
303	
304		// queued / running：先把取消终态写入原记录，确认原子替换成功后才让取消
305		// 生效。持锁期间外界观察不到中间态；若创建临时记录或替换原记录失败，
306		// 必须逐字段回滚，内存与磁盘都保持取消前的原状并返回实际保存错误，
307		// 不能把这次取消当作已完成。
308		now := s.now().UTC()
309		prevStatus := j.status
310		prevFinishedAt := j.finishedAt
311		prevReason := j.failureReason
312		prevBlocker := j.blockerID
313		prevEffective := j.effectiveValues
314		prevArchive := j.archive
315		j.status = StatusCanceled
316		j.failureReason = ""
317		j.blockerID = 0
318		if j.finishedAt.IsZero() {
319			j.finishedAt = now
320		}
321		j.effectiveValues = nil
322		j.archive = nil
323		if err := s.persist(j); err != nil {
324			j.status = prevStatus
325			j.finishedAt = prevFinishedAt
326			j.failureReason = prevReason
327			j.blockerID = prevBlocker
328			j.effectiveValues = prevEffective
329			j.archive = prevArchive
330			return nil, err
331		}
332	
333		// 取消已确认保存：提交终态，让正在运行的计算尽快中止，并级联标记下游。
334		j.canceled.Store(true)
335		// 依赖它的等待者一并失败，且继续向更下游传播。
336		s.cascadeLocked()
337		s.notifyLocked()
338		return s.viewLocked(j), nil
339	}
340	
341	// List 按提交人和提交时间范围（两端均包含）列出记录，结果按提交先后排列。
342	// start 晚于 end 返回 [ErrInvalidTimeRange]。零值时间表示该端不限。
343	func (s *Store) List(submitter string, start, end time.Time) ([]*Job, error) {
344		s.mu.Lock()
345		defer s.mu.Unlock()
346		if !start.IsZero() && !end.IsZero() && start.After(end) {
347			return nil, fmt.Errorf("%w：起始时间 %s 晚于结束时间 %s",
348				ErrInvalidTimeRange, start.Format(time.RFC3339Nano), end.Format(time.RFC3339Nano))
349		}
350		out := make([]*Job, 0)
351		for _, j := range s.jobs { // jobs 已按 id 升序，即提交先后
352			if j.submitter != submitter {
353				continue
354			}
355			if !start.IsZero() && j.queuedAt.Before(start) {
356				continue
357			}
358			if !end.IsZero() && j.queuedAt.After(end) {
359				continue
360			}
361			out = append(out, s.viewLocked(j))
362		}
363		return out, nil
364	}
365	
366	// cascadeLocked 把“直接上游已失败/取消”的排队作业标记为失败并递归传播。
367	//
368	// 上游在提交时必须已存在，因此上游作业号必然更小，按作业号升序单趟
369	// 扫描即可让阻断沿链条传播到最下游。作业有多个直接上游时，按列表顺序
370	// 选取最靠前的已失败/取消者作为直接阻断者；作业一旦失败，其原因不再被
371	// 后来发生的上游状态变化改写。
372	func (s *Store) cascadeLocked() {
373		for _, j := range s.jobs {
374			if j.status != StatusQueued || len(j.dependencies) == 0 {
375				continue
376			}
377			var direct *storedJob
378			for _, id := range j.dependencies {
379				dep := s.byID[id]
380				if dep == nil {
381					continue
382				}
383				if dep.status == StatusFailed || dep.status == StatusCanceled {
384					direct = dep
385					break
386				}
387			}
388			if direct == nil {
389				continue
390			}
391			root := direct.blockerID
392			if root == 0 {
393				root = direct.id
394			}
395			s.markFailedLocked(j, blockedReason(direct, root), root)
396		}
397	}
398	
399	func blockedReason(dep *storedJob, root uint64) string {
400		state := "失败"
401		if dep.status == StatusCanceled {
402			state = "被取消"
403		}
404		reason := fmt.Sprintf("直接上游作业 %d 已%s，阻断本作业继续计算", dep.id, state)
405		if dep.status == StatusFailed && dep.failureReason != "" {
406			reason += "（其失败原因：" + dep.failureReason + "）"
407		}
408		if root != dep.id {
409			reason += fmt.Sprintf("；阻断根因为作业 %d", root)
410		}
411		return reason
412	}
413	
414	// pickRunnableLocked 返回提交顺序上第一个可运行的排队作业。
415	// 可运行要求全部直接上游都已成功并归档；只要还有一个上游在排队或运行，
416	// 该作业就被跳过，不挡住后面可运行的作业。
417	func (s *Store) pickRunnableLocked() *storedJob {
418		for _, j := range s.jobs {
419			if j.status != StatusQueued {
420				continue
421			}
422			if len(j.dependencies) == 0 {
423				return j
424			}
425			ready := true
426			for _, id := range j.dependencies {
427				dep := s.byID[id]
428				if dep == nil || dep.status != StatusSucceeded {
429					ready = false
430					break
431				}
432			}
433			if ready {
434				return j
435			}
436		}
437		return nil
438	}
439	
440	// notifyLocked 在持锁状态下非阻塞唤醒 worker。
441	func (s *Store) notifyLocked() {
442		select {
443		case s.waitCh <- struct{}{}:
444		default:
445		}
446	}
447	
448	// notify 在不持锁时唤醒 worker。
449	func (s *Store) notify() {
450		s.mu.Lock()
451		s.notifyLocked()
452		s.mu.Unlock()
453	}
454	
455	// persistRetry 对落盘做有限次重试，尽量避免内存状态与磁盘记录分叉。
456	func (s *Store) persistRetry(j *storedJob, attempts int) error {
457		var err error
458		for i := 0; i < attempts; i++ {
459			if err = s.persist(j); err == nil {
460				return nil
461			}
462		}
463		return err
464	}
465	
466	// worker 是本地唯一的计算执行体。
467	func (s *Store) worker() {
468		defer s.wg.Done()
469		for {
470			s.mu.Lock()
471			if s.stopping.Load() {
472				s.mu.Unlock()
473				return
474			}
475			j := s.pickRunnableLocked()
476			if j == nil {
477				ch := s.waitCh
478				s.mu.Unlock()
479				select {
480				case <-ch:
481				case <-s.stopCh:
482				}
483				continue
484			}
485	
486			// 进入运行并原子持久化该状态。
487			j.status = StatusRunning
488			j.startedAt = s.now().UTC()
489			// 实际输入 = 原始序列 + 各直接上游的总和（严格按列表顺序追加）。
490			inputs := append([]int64(nil), j.values...)
491			for _, id := range j.dependencies {
492				if dep := s.byID[id]; dep != nil && dep.archive != nil {
493					inputs = append(inputs, dep.archive.Sum)
494				}
495			}
496			seed := j.seed
497			s.runningID = j.id
498			if err := s.persistRetry(j, 3); err != nil {
499				// 连运行状态都无法落盘：保守地失败，不进行计算。
500				s.markFailedLocked(j, "无法持久化作业状态："+err.Error(), 0)
501				s.runningID = 0
502				s.cascadeLocked()
503				s.notifyLocked()
504				s.mu.Unlock()
505				continue
506			}
507			s.mu.Unlock()
508	
509			abort := func() bool { return j.canceled.Load() || s.stopping.Load() }
510			doCompute := s.compute
511			if doCompute == nil {
512				doCompute = func(_ uint64, in []int64, sd int64, c func() bool) (int64, int64, string, bool) {
513					return computeResult(in, sd, c)
514				}
515			}
516			sum, sumSq, reason, ok := doCompute(j.id, inputs, seed, abort)
517	
518			s.mu.Lock()
519			s.runningID = 0
520			switch {
521			case j.status == StatusCanceled:
522				// 用户取消已在 Cancel 中落盘；此处确保丢弃任何计算产物。
523				j.archive = nil
524				j.effectiveValues = nil
525				_ = s.persistRetry(j, 3)
526				s.cascadeLocked()
527			case s.stopping.Load():
528				s.markFailedLocked(j, "计算被中断：归档在计算过程中关闭", 0)
529				s.cascadeLocked()
530			case !ok:
531				s.markFailedLocked(j, reason, 0)
532				s.cascadeLocked()
533			default:
534				// 成功：状态与完整归档在同一条记录的同一次原子写入中可见。
535				completed := s.now().UTC()
536				a := newArchive(j, inputs, sum, sumSq, completed)
537				j.effectiveValues = append([]int64(nil), inputs...)
538				j.status = StatusSucceeded
539				j.finishedAt = completed
540				j.failureReason = ""
541				j.blockerID = 0
542				j.archive = a
543				if err := s.persistRetry(j, 3); err != nil {
544					// 落盘失败时绝不让对外可见“成功却没有归档”：回退为失败。
545					j.archive = nil
546					j.effectiveValues = nil
547					s.markFailedLocked(j, "结果归档写入失败："+err.Error(), 0)
548					// 归档写入失败与计算溢出等失败同等对待：立即沿依赖链阻断所有仍在
549					// 排队等待它的作业，使等待者无需等到下一次提交/取消即进入失败终态。
550					s.cascadeLocked()
551				}
552			}
553			s.notifyLocked()
554			s.mu.Unlock()
555		}
556	}
557	
558	// markFailedLocked 在持锁状态下把作业置为失败终态并尝试落盘。
559	func (s *Store) markFailedLocked(j *storedJob, reason string, blocker uint64) {
560		j.status = StatusFailed
561		j.failureReason = reason
562		j.blockerID = blocker
563		if j.finishedAt.IsZero() {
564			j.finishedAt = s.now().UTC()
565		}
566		j.archive = nil
567		j.effectiveValues = nil
568		_ = s.persistRetry(j, 3)
569	}
570	
571	// newArchive 构造成功归档；CompletedAt 之外的全部字段都是确定性的。
572	// 上游作业号只作记录，不参与任何摘要与校验值。
573	func newArchive(j *storedJob, effective []int64, sum, sumSquares int64, completedAt time.Time) *Archive {
574		inDigest := inputsDigestHex(effective, j.seed)
575		resDigest := resultDigestHex(effective, j.seed, sum, sumSquares)
576		log := buildLog(effective, j.seed, sum, sumSquares)
577		checksum := checksumHex(effective, j.seed, sum, sumSquares, log, resDigest)
578		var firstDep uint64
579		if len(j.dependencies) > 0 {
580			firstDep = j.dependencies[0]
581		}
582		return &Archive{
583			JobID:           j.id,
584			Submitter:       j.submitter,
585			RequestID:       j.requestID,
586			Seed:            j.seed,
587			Values:          append([]int64(nil), j.values...),
588			HasDependency:   len(j.dependencies) > 0,
589			DependencyID:    firstDep,
590			Dependencies:    append([]uint64(nil), j.dependencies...),
591			EffectiveValues: append([]int64(nil), effective...),
592			InputsDigest:    inDigest,
593			Sum:             sum,
594			SumOfSquares:    sumSquares,
595			ResultDigest:    resDigest,
596			Log:             log,
597			Checksum:        checksum,
598			CompletedAt:     completedAt,
599		}
600	}
601	
602	// viewLocked 在持锁状态下生成对外只读视图，全部切片深拷贝。
603	func (s *Store) viewLocked(j *storedJob) *Job {
604		v := &Job{
605			ID:              j.id,
606			Submitter:       j.submitter,
607			RequestID:       j.requestID,
608			Seed:            j.seed,
609			Values:          append([]int64(nil), j.values...),
610			Dependencies:    append([]uint64(nil), j.dependencies...),
611			QueuedAt:        j.queuedAt,
612			StartedAt:       j.startedAt,
613			FinishedAt:      j.finishedAt,
614			Status:          j.status,
615			FailureReason:   j.failureReason,
616			BlockerID:       j.blockerID,
617			EffectiveValues: append([]int64(nil), j.effectiveValues...),
618		}
619		v.HasDependency = len(j.dependencies) > 0
620		if len(j.dependencies) > 0 {
621			v.DependencyID = j.dependencies[0]
622		}
623		if j.status == StatusQueued {
624			v.WaitReason = WaitSlot
625			// 列出尚未成功归档的直接上游，保持提交时的顺序。
626			for _, id := range j.dependencies {
627				if dep := s.byID[id]; dep == nil || dep.status != StatusSucceeded {
628					v.PendingDependencies = append(v.PendingDependencies, id)
629				}
630			}
631			if len(v.PendingDependencies) > 0 {
632				v.WaitReason = WaitDependency
633			}
634		}
635		if j.archive != nil {
636			a := *j.archive
637			a.Values = append([]int64(nil), j.archive.Values...)
638			a.EffectiveValues = append([]int64(nil), j.archive.EffectiveValues...)
639			a.Dependencies = append([]uint64(nil), j.archive.Dependencies...)
640			v.Archive = &a
641		}
642		return v
643	}
644	
645	// Dir 返回归档目录路径。
646	func (s *Store) Dir() string { return s.dir }
647

