1	package numeric
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// nul 是实际的 U+0000 字符；提交人与请求号都允许包含它，两个标识必须按
10	// 调用方给出的完整字符串区分，不能用分隔符拼接（否则下列两对
11	// (提交人, 请求号) 会塌缩成同一个键）：
12	//
13	//	("a",      "b\x00c")
14	//	("a\x00b", "c")
15	const nul = "\x00"
16	
17	// TestNULSubmitterRequestIDAreDistinctKeys 覆盖核心串用缺陷：两对标识只是
18	// 把同一个零字符摆在了分隔符的两侧，必须被视为互不相关的提交。
19	func TestNULSubmitterRequestIDAreDistinctKeys(t *testing.T) {
20		s, _ := openTestStore(t)
21	
22		// 内容完全相同（整数序列、种子、依赖都一致）也不能当成同一次请求。
23		req1 := SubmitRequest{
24			Submitter: "a", RequestID: "b" + nul + "c",
25			Values: []int64{1, 2, 3}, Seed: 7,
26		}
27		req2 := SubmitRequest{
28			Submitter: "a" + nul + "b", RequestID: "c",
29			Values: []int64{1, 2, 3}, Seed: 7,
30		}
31		j1 := mustSubmit(t, s, req1)
32		j2 := mustSubmit(t, s, req2) // 旧实现会在此处串用 j1 或误报幂等冲突
33		if j1.ID == j2.ID {
34			t.Fatalf("两组标识串用：都得到作业号 %d", j1.ID)
35		}
36		d1 := waitStatus(t, s, j1.ID, StatusSucceeded)
37		d2 := waitStatus(t, s, j2.ID, StatusSucceeded)
38		if d1.Submitter != req1.Submitter || d1.RequestID != req1.RequestID {
39			t.Fatalf("作业 %d 标识错误：%q %q", j1.ID, d1.Submitter, d1.RequestID)
40		}
41		if d2.Submitter != req2.Submitter || d2.RequestID != req2.RequestID {
42			t.Fatalf("作业 %d 标识错误：%q %q", j2.ID, d2.Submitter, d2.RequestID)
43		}
44	
45		// 计算内容不同：第二组仍必须作为新作业接受，不能返回另一提交人的作业
46		// 视图，也不能报幂等冲突。
47		j3, err := s.Submit(SubmitRequest{
48			Submitter: "a" + nul + "b", RequestID: "c2",
49			Values: []int64{9}, Seed: 7,
50		})
51		if err != nil {
52			t.Fatalf("不同内容的新标识组合被拒绝：%v", err)
53		}
54		if j3.ID == j1.ID || j3.ID == j2.ID {
55			t.Fatalf("新提交串用了已有作业号：%d", j3.ID)
56		}
57		waitStatus(t, s, j3.ID, StatusSucceeded)
58	
59		// 按作业号读取：标识与参数各自准确。
60		g1, _ := s.Get(j1.ID)
61		g2, _ := s.Get(j2.ID)
62		if g1.Submitter != "a" || g1.RequestID != "b"+nul+"c" {
63			t.Fatalf("Get(%d)=%q,%q", j1.ID, g1.Submitter, g1.RequestID)
64		}
65		if g2.Submitter != "a"+nul+"b" || g2.RequestID != "c" {
66			t.Fatalf("Get(%d)=%q,%q", j2.ID, g2.Submitter, g2.RequestID)
67		}
68		if g1.Archive == nil || g1.Archive.Submitter != "a" || g1.Archive.RequestID != "b"+nul+"c" {
69			t.Fatalf("作业 %d 归档未原样保留提交信息：%+v", j1.ID, g1.Archive)
70		}
71		if g2.Archive == nil || g2.Archive.Submitter != "a"+nul+"b" || g2.Archive.RequestID != "c" {
72			t.Fatalf("作业 %d 归档未原样保留提交信息：%+v", j2.ID, g2.Archive)
73		}
74	
75		// 按提交人列举：含零字符的提交人也是完整匹配，互不可见。
76		l1, _ := s.List("a", time.Time{}, time.Time{})
77		l2, _ := s.List("a"+nul+"b", time.Time{}, time.Time{})
78		if len(l1) != 1 || l1[0].ID != j1.ID {
79			var ids []uint64
80			for _, j := range l1 {
81				ids = append(ids, j.ID)
82			}
83			t.Fatalf("List(\"a\")=%v，应只含作业 %d", ids, j1.ID)
84		}
85		if len(l2) != 2 || l2[0].ID != j2.ID || l2[1].ID != j3.ID {
86			var ids []uint64
87			for _, j := range l2 {
88				ids = append(ids, j.ID)
89			}
90			t.Fatalf("List(\"a\\x00b\")=%v，应含作业 %d,%d", ids, j2.ID, j3.ID)
91		}
92	}
93	
94	// TestNULIdempotencyWithinSameIdentity ：同一完整（提交人, 请求号）的幂等
95	// 语义在标识含零字符时保持不变：同内容重放返回原作业；整数序列内容/次序、
96	// 种子、依赖内容/次序变化报冲突并返回原作业视图。
97	func TestNULIdempotencyWithinSameIdentity(t *testing.T) {
98		s, _ := openTestStore(t)
99		sub := "x" + nul + "y"
100		req := "r" + nul + "q"
101		base := mustSubmit(t, s, SubmitRequest{
102			Submitter: sub, RequestID: req, Values: []int64{1, 2}, Seed: 4,
103		})
104		waitStatus(t, s, base.ID, StatusSucceeded)
105	
106		// 完全相同 → 原作业、当前状态，不增加记录。
107		again, err := s.Submit(SubmitRequest{
108			Submitter: sub, RequestID: req, Values: []int64{1, 2}, Seed: 4,
109		})
110		if err != nil || again.ID != base.ID || again.Status != StatusSucceeded {
111			t.Fatalf("同内容重放：id=%d status=%s err=%v", replayID(again), again.Status, err)
112		}
113		if got, _ := s.List(sub, time.Time{}, time.Time{}); len(got) != 1 {
114			t.Fatalf("重放增加了记录：%d", len(got))
115		}
116	
117		variants := []SubmitRequest{
118			{Submitter: sub, RequestID: req, Values: []int64{2, 1}, Seed: 4}, // 次序变化
119			{Submitter: sub, RequestID: req, Values: []int64{1, 3}, Seed: 4}, // 内容变化
120			{Submitter: sub, RequestID: req, Values: []int64{1, 2}, Seed: 5}, // 种子变化
121		}
122		for i, v := range variants {
123			j, err := s.Submit(v)
124			if !errors.Is(err, ErrIdempotencyConflict) {
125				t.Fatalf("变体 %d：err=%v，要幂等冲突", i, err)
126			}
127			if j == nil || j.ID != base.ID || j.Submitter != sub || j.RequestID != req {
128				t.Fatalf("变体 %d 的冲突视图不是原作业：%+v", i, j)
129			}
130		}
131	
132		// 依赖内容/次序变化也是冲突；单依赖方式与只含同一上游的列表是相同内容。
133		dep1 := mustSubmit(t, s, SubmitRequest{Submitter: sub, Values: []int64{10}})
134		dep2 := mustSubmit(t, s, SubmitRequest{Submitter: sub, Values: []int64{20}})
135		waitStatus(t, s, dep1.ID, StatusSucceeded)
136		waitStatus(t, s, dep2.ID, StatusSucceeded)
137	
138		withList := SubmitRequest{
139			Submitter: sub, RequestID: "dep" + nul, Values: []int64{1, 2}, Seed: 4,
140			Dependencies: []uint64{dep1.ID},
141		}
142		jl := mustSubmit(t, s, withList)
143		waitStatus(t, s, jl.ID, StatusSucceeded)
144		// 单依赖方式重放同一上游：相同内容，返回原作业。
145		single := withList
146		single.Dependencies = nil
147		single.HasDependency = true
148		single.DependencyID = dep1.ID
149		if replay, err := s.Submit(single); err != nil || replay.ID != jl.ID {
150			t.Fatalf("单依赖与单元素列表应等价：id=%d err=%v，要 %d", replayID(replay), err, jl.ID)
151		}
152		// 依赖次序变化 → 冲突：先以两上游列表建立基线，再调换次序提交。
153		two := withList
154		two.RequestID = "two" + nul
155		two.Dependencies = []uint64{dep1.ID, dep2.ID}
156		jtwo := mustSubmit(t, s, two)
157		waitStatus(t, s, jtwo.ID, StatusSucceeded)
158		swapped := two
159		swapped.Dependencies = []uint64{dep2.ID, dep1.ID}
160		if j, err := s.Submit(swapped); !errors.Is(err, ErrIdempotencyConflict) ||
161			j == nil || j.ID != jtwo.ID {
162			t.Fatalf("依赖次序变化应冲突并返回原作业 %d：j=%+v err=%v", jtwo.ID, j, err)
163		}
164	}
165	
166	// TestNULRequestIDNonEmptyEnablesIdempotency ：只含零字符的请求号属于非空
167	// 请求号，重复提交必须找到自己的原作业；空请求号仍不启用幂等。
168	func TestNULRequestIDNonEmptyEnablesIdempotency(t *testing.T) {
169		s, _ := openTestStore(t)
170		withNUL := mustSubmit(t, s, SubmitRequest{
171			Submitter: "a", RequestID: nul, Values: []int64{1, 2},
172		})
173		waitStatus(t, s, withNUL.ID, StatusSucceeded)
174		again, err := s.Submit(SubmitRequest{
175			Submitter: "a", RequestID: nul, Values: []int64{1, 2},
176		})
177		if err != nil || again.ID != withNUL.ID {
178			t.Fatalf("零字符请求号重放：id=%d err=%v，要 %d", replayID(again), err, withNUL.ID)
179		}
180		// 两个零字符与一个零字符是不同的非空请求号。
181		twoNULs := mustSubmit(t, s, SubmitRequest{
182			Submitter: "a", RequestID: nul + nul, Values: []int64{1, 2},
