import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync/atomic"
	"time"
	"unicode/utf8"
)

// rawString 保存 Go 字符串的完整字节。JSON 文本字段只能承载合法 UTF-8：
// encoding/json 会把字符串中不能组成合法 UTF-8 的字节替换成 U+FFFD，
// 导致提交人/请求号在落盘后失真（不同标识塌缩成同一条记录）。
// 因此标识含非法 UTF-8 字节时，额外用 base64 原始字节字段兜底；
// 普通文本（含 U+0000，它本身是合法 UTF-8）仍走原字符串字段，
// 旧归档无需转换即可继续打开。
type rawString string

// marshalRaw 总是返回标识的完整字节：合法 UTF-8 时原样写入 JSON 字符串，
// 否则返回 base64 标准编码（非空且不可能以 '"' 开头，可与原写法区分）。
func marshalRaw(s string) []byte {
	if utf8.ValidString(s) {
		b, err := json.Marshal(s)
		if err == nil {
			return b
		}
	}
	return []byte(`"` + base64.StdEncoding.EncodeToString([]byte(s)) + `"`)
}

// unmarshalRaw 恢复 marshalRaw 写出的字段；普通 JSON 字符串经
// encoding/json 解码即可原样得到，base64 兜底值在此解码回原始字节。
func unmarshalRaw(s string) (string, error) {
	if len(s) > 0 {
		if b, err := base64.StdEncoding.DecodeString(s); err == nil {
			return string(b), nil
		}
	}
	return s, nil
}

// identityRaw 携带提交人、请求号的完整字节兜底表示。只有当对应字段含
// 非法 UTF-8 字节时相应成员才非空；普通文本记录不写这两个字段，
// 保持旧格式归档可直接打开。
type identityRaw struct {
	Submitter string `json:"submitter_raw,omitempty"`
	RequestID string `json:"request_id_raw,omitempty"`
}

